-- PROLIMSO Zona Sur · Cartera de transportistas (agencias) para el cierre de pedido de clientes de cartera
create table if not exists public.transportistas (
  id bigserial primary key,
  codigo text not null default '',
  nombre text not null,
  direccion text not null default '',
  ruc text not null default '',
  telefono text not null default '',
  activo boolean not null default true,
  created_at timestamptz not null default now()
);
create unique index if not exists transportistas_nombre_ruc_uq on public.transportistas (upper(nombre), ruc);
alter table public.transportistas enable row level security;
drop policy if exists "transportistas: solo admin" on public.transportistas;
create policy "transportistas: solo admin" on public.transportistas for all using (public.is_admin()) with check (public.is_admin());

-- Lista para el cotizador: solo clientes de cartera con clave válida (usa el mismo bloqueo por intentos que cliente_acceso).
-- 'lista' = [[agencia, telefono], ...]; 'mis' = datos que ese cliente usó la última vez con cada agencia.
create or replace function public.cliente_transportes(p_doc text, p_clave text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare a jsonb; lst jsonb; mis jsonb;
begin
  a := public.cliente_acceso(p_doc, p_clave);
  if coalesce((a->>'ok')::boolean, false) is not true then return jsonb_build_object('ok', false); end if;
  select coalesce(jsonb_agg(jsonb_build_array(nombre, telefono) order by nombre), '[]'::jsonb) into lst from public.transportistas where activo;
  select coalesce(jsonb_object_agg(k, d), '{}'::jsonb) into mis from (
    select distinct on (upper(origen->'transporte'->>'agencia')) upper(origen->'transporte'->>'agencia') as k, origen->'transporte'->>'datos' as d
    from public.pedidos
    where doc_num = regexp_replace(coalesce(p_doc,''), '\D', '', 'g') and coalesce(origen->'transporte'->>'agencia','') <> ''
    order by upper(origen->'transporte'->>'agencia'), created_at desc) t;
  return jsonb_build_object('ok', true, 'lista', lst, 'mis', mis);
end $$;
revoke all on function public.cliente_transportes(text, text) from public;
grant execute on function public.cliente_transportes(text, text) to anon, authenticated;

on conflict do nothing;

select count(*) as transportistas from public.transportistas;
